// Hooijmans et al. BMC Med Res Methodol 2014;14:43 (CC BY 2.0), for animal studies in a review: ten
// entries under six types of bias. A Yes to an entry's signalling questions is low risk, a No high
// risk; the tool recommends no summary score, so there is no overall.
const syrcle = {
  id: 'syrcle',
  name: 'SYRCLE risk of bias',
  design: 'Animal intervention studies',
  judgements: ['Low', 'High', 'Unclear'],
  source: { url: 'https://doi.org/10.1186/1471-2288-14-43', note: 'Hooijmans et al. BMC Med Res Methodol 2014;14:43. Entry numbers and bias types as published; labels are our own paraphrase; Yes to the signalling questions is low risk' },
  overall: false,
  domains: [
    ['Selection bias', 'Allocation sequence adequately generated and applied'],
    ['Selection bias', 'Groups similar at baseline or adjusted for confounders'],
    ['Selection bias', 'Allocation concealed from those assigning animals'],
    ['Performance bias', 'Animals housed at random during the experiment'],
    ['Performance bias', 'Caregivers and investigators blinded to the intervention'],
    ['Detection bias', 'Animals selected at random for outcome assessment'],
    ['Detection bias', 'Outcome assessor blinded'],
    ['Attrition bias', 'Incomplete outcome data adequately addressed'],
    ['Reporting bias', 'Free of selective outcome reporting'],
    ['Other', 'Free of other problems that could cause a high risk of bias'],
  ].map(([group, label], i) => ({ id: `d${i + 1}`, short: String(i + 1), label, group })),
};

// ---- AQUA tool (plan W7) ---------------------------------------------------------------------------
// Henry et al. Clin Anat 2017;30:6–13, for anatomical studies in a meta-analysis: five domains, each at
// low, high or unclear risk of bias. The domain names were read in a meta-analysis that applied the
// tool, not in the original article; the signalling questions are left to the source, as for ROBIS.
const aquaTool = {
  id: 'aqua-tool',
  name: 'AQUA tool',
  design: 'Anatomical studies',
  judgements: ['Low', 'High', 'Unclear'],
  judgementOnly: true,
  source: { url: 'https://doi.org/10.1002/ca.22799', note: 'Henry et al. Clin Anat 2017;30:6–13. Domain names as applied in published meta-analyses; judgement only, the signalling questions are in the source' },
  overall: false,
  domains: [
    'Objectives and subject characteristics',
    'Study design',
    'Methodology characterization',
    'Descriptive anatomy',
    'Reporting of results',
  ].map((label, i) => ({ id: `d${i + 1}`, short: `D${i + 1}`, label })),
};

// ---- QUADAS-C ---------------------------------------------------------------------------------------

// QUADAS-C (Yang et al. 2021): the comparative extension of QUADAS-2 for studies that compare two or more index tests. Each of the four
// QUADAS-2 domains gains comparative signalling questions (C1.1 to C4.4) and a comparative risk-of-bias judgement (C1.5, C2.5, C3.3, C4.5:
// Low, High or Unclear). Question C-x.1 asks whether the QUADAS-2 risk-of-bias judgement of every index test in that domain was low, so
// QUADAS-C is answered beside QUADAS-2 for each test, not instead of it. Question text is our paraphrase (source: tool document of the
// Bristol QUADAS site; its reuse terms are not stated). The tool states a rule for 'low' and a consideration for 'high' only; it states
// none for 'unclear', which the reviewer judges (quadasCRule never returns it).
const QUADAS_C_DESIGNS = ['Fully paired', 'Randomized', 'Partially paired, random subset', 'Partially paired, nonrandom subset', 'Unpaired nonrandomized or other'];
const QC_PAIRED = new Set([QUADAS_C_DESIGNS[0], QUADAS_C_DESIGNS[2], QUADAS_C_DESIGNS[3]]);
// signalling questions per domain; `only` limits a question to randomized or paired designs, as the tool does
const QUADAS_C_QUESTIONS = {
  c1: [['C1.1', 'Each index test judged low risk of bias for patient selection'], ['C1.2', 'Fully paired or randomized design used'],
    ['C1.3', 'Allocation sequence random', 'randomized'], ['C1.4', 'Allocation sequence concealed until patients enrolled and assigned', 'randomized']],
  c2: [['C2.1', 'Each index test judged low risk of bias for the index test domain'], ['C2.2', 'Index test results interpreted blind to the other index tests', 'paired'],
    ['C2.3', 'One index test unlikely to affect the performance of the other', 'paired'], ['C2.4', 'Tests conducted and interpreted without advantaging one test']],
  c3: [['C3.1', 'Each index test judged low risk of bias for the reference standard'], ['C3.2', 'Reference standard avoided incorporating any index test']],
  c4: [['C4.1', 'Each index test judged low risk of bias for flow and timing'], ['C4.2', 'Appropriate interval between the index tests'],
    ['C4.3', 'Same reference standard used for all index tests'], ['C4.4', 'Proportions and reasons for missing data similar across index tests']],
};
const qcApplies = (only, design) => !only || (only === 'randomized' ? design === QUADAS_C_DESIGNS[1] : QC_PAIRED.has(design));
/**
 * What the tool's own rule says about one comparative domain, from the answers to its questions ({ 'C1.1': 'Yes', … }) and the design
 * class: `{ applicable, low, no, strongHigh }`. `low` when every applicable question is answered Yes; `no` lists the questions answered
 * No (the tool: consider High when the design feature is of such concern that the whole domain is problematic; C1.2 No: strongly consider
 * High). The judgement is the reviewer's; the tool gives no rule for Unclear.
 */
function quadasCRule(domainId, answers = {}, design = '') {
  const applicable = (QUADAS_C_QUESTIONS[domainId] || []).filter(([, , only]) => qcApplies(only, design)).map(([id]) => id);
  const no = applicable.filter(id => answers[id] === 'No');
  return { applicable, low: applicable.length > 0 && applicable.every(id => answers[id] === 'Yes'), no, strongHigh: domainId === 'c1' && no.includes('C1.2') };
}
const qcSignals = d => QUADAS_C_QUESTIONS[d].map(([id, text, only]) => `${id} ${text}${only === 'randomized' ? ' (randomized designs only)' : only === 'paired' ? ' (paired designs only)' : ''}`);
const quadasC = {
  id: 'quadas-c',
  name: 'QUADAS-C',
  design: 'Comparative diagnostic accuracy studies',
  judgements: ['Low', 'High', 'Unclear'],
  source: { url: 'https://www.bristol.ac.uk/population-health-sciences/projects/quadas/quadas-c/', note: 'Yang et al. Ann Intern Med 2021;174:1592–9. Question numbers as published; wording is our own paraphrase; reuse terms not stated. Answered beside QUADAS-2 for each index test' },
  overall: false,
  domains: [
    { id: 'design', short: 'Des', label: 'Comparative design: how the tests were compared, fully paired to unpaired', judgements: QUADAS_C_DESIGNS },
    { id: 'c1', short: 'C1', label: 'Patient selection, comparative risk of bias: could selection have biased the comparison', signals: qcSignals('c1') },
    { id: 'c2', short: 'C2', label: 'Index test, comparative risk of bias: could conduct or reading have biased the comparison', signals: qcSignals('c2') },
    { id: 'c3', short: 'C3', label: 'Reference standard, comparative risk of bias: could it have biased the comparison', signals: qcSignals('c3') },
    { id: 'c4', short: 'C4', label: 'Flow and timing, comparative risk of bias: could patient flow have biased the comparison', signals: qcSignals('c4') },
  ],
};

// ---- the set, and the tones their judgement levels need ------------------------------------

const EXTRA_TOOLS = [nosCohort, nosCaseControl, minors, rob1, ...mmatTools, quips, ...jbiTools, agree, syrcle, aquaTool, quadasC];

/**
 * Judgement levels these instruments add to schema.mjs's JUDGEMENT_TONE.
 * Stars and MINORS points read as favourable to unfavourable, as they are
 * scored. AGREE II has no traffic-light convention, so its levels are neutral.
 */
const EXTRA_JUDGEMENT_TONE = {
  [STAR]: 'good', [TWO]: 'good', [NONE$1]: 'bad',
  'Reported, adequate': 'good', 'Reported, inadequate': 'unclear', 'Not reported': 'bad',
  ...Object.fromEntries([...AGREE_LEVELS, ...Object.keys(AGREE_OLD)].map(l => [l, 'none'])),
  'Yes with modifications': 'unclear',
  ...Object.fromEntries(QUADAS_C_DESIGNS.map(l => [l, 'none'])),
};

/** The score an instrument defines for one study's answers, or null when it defines none. */
function scoreOf(tool, answers) {
  if (tool?.scoring === 'nos') return nosScore(tool, answers);
  if (tool?.scoring === 'minors') return minorsScore(answers);
  if (tool?.scoring === 'agree') return agreeScores([answers]);
  return null;
}
